mapper.insert:
INSERT INTO ITEM (
   ITEM_NO, ITEM_NM, ITEM_PRICE, SALE_PRICE, ITEM_DEL
) VALUES (
   (SELECT NVL(MAX(ITEM_NO),0)+1 FROM ITEM),
   #{itemNm}, #{itemPrice}, #{salePrice}, 1
)

mapper.update:
UPDATE ITEM
SET ITEM_NM = #{itemNm},
   ITEM_PRICE = #{itemPrice},
   Sale_PRICE = #{salePrice}
WHERE ITEM_NO = #{itemNo}

mapper.select:
SELECT ITEM_NO, ITEM_NM, ITEM_PRICE, SALE_PRICE FROM ITEM WHERE ITEM_NO IN
#{itemNo}
AND ITEM_DEL = 1

mapper.update:
UPDATE ITEM SET ITEM_DEL = 2 WHERE ITEM_NO IN
#{itemNo}
AND ITEM_DEL = 1
